'use strict';
const CHAPTERS=[['/visao/','Visão','A ideia'],['/arquitetura/','Arquitetura','A estrutura'],['/composicoes/','Composições','As conexões'],['/studio/','Studio','A construção'],['/workflows/','Workflows','O movimento'],['/agentes/','Agentes IA','A interação'],['/governanca/','Governança','A responsabilidade'],['/desenvolvedores/','Desenvolvedores','Os contratos']];
function chapterNav(){return `<nav class="chapter-nav container" aria-label="Explorar a plataforma">${CHAPTERS.map(([u,n])=>`<a href="${u}" ${ROUTE===u.slice(0,-1)?'aria-current="page"':''}>${n}</a>`).join('')}</nav>`}
const priorHeader=header;
header=function(){return priorHeader().replace(/<div class="review-banner">[\s\S]*?<\/div>/,'').replace('<a class="contact-link"',`<details class="explore-menu"><summary>Explorar <span>＋</span></summary><div class="explore-panel"><div><small>MARCA E PLATAFORMA</small>${CHAPTERS.map(([u,n,d])=>`<a href="${u}"><b>${n}</b><span>${d} ↗</span></a>`).join('')}</div><div><small>CONSTRUÍDO COM CATALISA</small>${PRODUCTS.map(p=>`<a href="/ecossistema/${p.slug}/"><b>${p.name}</b><span>Ver produto ↗</span></a>`).join('')}<a href="/interfaces/">Interfaces de referência ↗</a><a href="/mapa/">Todas as páginas ↗</a></div></div></details><a class="contact-link"`)};
function nextChapter(url,title,desc){return fSection(`<a class="next-chapter" href="${url}"><div>${eyebrow('Continue explorando')}<h2>${title}</h2><p>${desc}</p></div><span aria-hidden="true">↗</span></a>`,'next-section')}
function quietDetails(title,body){return `<details class="quiet-details"><summary>${title}<span aria-hidden="true">＋</span></summary><div>${body}</div></details>`}
function signalDrawing(){return `<svg class="signal-study" viewBox="0 0 1000 330" role="img" aria-label="Estudo visual: linhas dispersas se organizam em um sinal contínuo"><defs><linearGradient id="signal-ink"><stop stop-color="#734b9c" stop-opacity=".1"/><stop offset=".6" stop-color="#734b9c" stop-opacity=".8"/><stop offset="1" stop-color="#734b9c"/></linearGradient></defs>${Array.from({length:34},(_,i)=>`<path style="--i:${i}" d="M20 ${35+i*8} C${150+i%5*18} ${330-i*10},${310+i%7*12} ${-130+i*15},500 165 S680 ${i%2?5:325},980 165" fill="none" stroke="url(#signal-ink)" stroke-width=".8"/>`).join('')}<circle cx="680" cy="165" r="32" fill="#fdc234"/><path d="M500 165H980" stroke="#734b9c" fill="none"/><circle class="signal-pulse" cx="900" cy="165" r="4" fill="#734b9c"/></svg>`}
function artHero(tag,title,desc,artwork,cls=''){return `<section class="art-hero ${cls}"><div class="container">${eyebrow(tag)}<h1>${title}</h1><div class="art-hero-bottom"><p>${desc}</p><span class="art-index">CATALISA / ESTUDO DE COMPOSIÇÃO</span></div></div><div class="art-hero-piece">${artwork}</div></section>`}
const quietHome=home;
home=function(){return `<section class="gallery-home"><div class="container">${eyebrow('Tecnologia por composição')}<h1>Dê forma ao<br>que vem depois.</h1><p>Da complexidade à construção.</p>${link('/arquitetura/','Explore a arquitetura','button outline')}</div><img src="${APPROVED}hero.png" alt="Da dispersão à estrutura: fios encontram módulos translúcidos" fetchpriority="high"><span class="work-caption">01 — A COMPLEXIDADE ENCONTRA FORMA</span></section>`+fSection(`<div class="quiet-statement"><h2>Uma base.<br>Infinitas composições.</h2><p>A Catalisa conecta dados, decisões e processos para construir produtos e operações.</p></div>`)+fSection(`<a class="architecture-exhibit" href="/arquitetura/"><div>${eyebrow('A estrutura')}<h2>O que sustenta<br>o próximo.</h2><span class="text-link">Conheça a arquitetura ↗</span></div><img src="${APPROVED}stack.png" alt="Camadas independentes em uma estrutura comum" loading="lazy"></a>`)+fSection(`<div class="quiet-statement"><h2>A base ganha<br>vida no contexto.</h2>${link('/ecossistema/','Explore o ecossistema')}</div><div class="product-ribbon">${PRODUCTS.map(p=>`<a href="/ecossistema/${p.slug}/">${productArt(p)}<h3>${p.name}</h3><span>${p.category} ↗</span></a>`).join('')}</div>`)+fSection(fPerspectives(),'sidebar-section perspectives-section')};
vision=function(){return chapterNav()+artHero('01 / Visão','Construir é<br>dar sentido.', 'Capacidades independentes encontram uma linguagem comum. A complexidade se torna estrutura.',signalDrawing(),'vision-art')+fSection(`<div class="reading-pair"><h2>O ruído encontra<br>uma intenção.</h2><div><p>Uma operação reúne pessoas, dados, regras e sistemas. Cada nova interface revela apenas parte desse trabalho.</p><p>A Catalisa organiza as capacidades que sustentam a operação para que novos produtos possam nascer da composição de uma base existente.</p></div></div>`)+fSection(`<div class="principle-trio">${[['Fronteira','Cada capacidade explica o que faz e onde termina.'],['Conexão','Contratos permitem combinar responsabilidades.'],['Expressão','O produto dá uma forma própria à mesma base.']].map(([n,d],i)=>`<div><span>0${i+1}</span><h3>${n}</h3><p>${d}</p></div>`).join('')}</div>`)+nextChapter('/arquitetura/','A ideia encontra estrutura.','Veja como as camadas se relacionam.')};
architecture=function(){return chapterNav()+artHero('02 / Arquitetura','Independente.<br>Em conjunto.','Identidade, dados, decisão e canais. Cada camada preserva sua responsabilidade.',`<img src="${APPROVED}stack.png" alt="Estudo de arquitetura explodida da plataforma">`,'stack-art')+fSection(`<div class="layer-explorer"><div><h2>Aprofunde<br>uma camada.</h2><p>Abra apenas o que você quer conhecer.</p></div><div>${F_LAYERS.map(([n,d,s],i)=>quietDetails(`<small>0${i+1}</small> ${n}`,`<p>${d}</p>${link(s==='workflows'?'/workflows/':'/capacidades/'+s+'/', 'Explore esta capacidade')}`)).join('')}</div></div>`)+fSection(`<div class="reading-pair"><h2>A esteira busca.<br>O motor decide.</h2><div><p>Decision Platform reúne as fontes declaradas. Decision Engine avalia a política DMN publicada. A composição conecta as duas responsabilidades.</p>${actions(link('/capacidades/decision-platform/','A esteira'),link('/capacidades/decision-engine/','O motor'))}</div></div>`)+nextChapter('/composicoes/','As conexões mudam o resultado.','Explore jornadas construídas com as capacidades.')};
compositions=function(){return chapterNav()+hero('03 / Composições','O todo ganha<br>outro sentido.','Uma capacidade mantém seu contrato. A combinação cria uma nova jornada.','modules')+fSection(composition())+fSection(`<div class="reading-pair"><h2>A mesma peça.<br>Outro contexto.</h2><div><p>Calendar participa de consultas, entrevistas e reuniões. Rooms conecta pessoas em diferentes jornadas. O contexto muda; a responsabilidade da capacidade permanece.</p>${actions(link('/capacidades/calendar/','Calendar'),link('/capacidades/rooms/','Rooms'))}</div></div>`)+nextChapter('/studio/','Comece pela intenção.','Da descrição ao desenho de uma composição.')};
const STUDIES={studio:{tag:'04 / Studio',title:'Uma ideia.<br>Depois, estrutura.',desc:'Descreva o trabalho. Refine o contexto. Encontre a composição.',i:2,heading:'Da linguagem natural<br>à especificação.',text:'O Studio parte da descrição de uma necessidade. A IA ajuda a refinar requisitos e organizar agentes e workflows conectados às capacidades da plataforma.',items:[['Descrever','Uma necessidade em linguagem natural ou um template inicia a construção.'],['Refinar','Contexto, ferramentas e comportamento esperado encontram uma especificação.'],['Compor','O workflow organiza os blocos e as responsabilidades da jornada.']],source:'https://catalisa.io/studio/',next:'/workflows/',nextTitle:'Coloque a intenção em movimento.'},workflows:{tag:'05 / Workflows',title:'Todo evento<br>abre um caminho.',desc:'Gatilhos, condições e ações tornam o trabalho legível.',i:2,heading:'O próximo passo<br>tem uma razão.',text:'Um lead, uma mensagem ou um webhook pode iniciar uma jornada. Condições orientam o caminho; ações conectam capacidades. O acompanhamento da execução ajuda a entender o resultado.',items:[['Evento','Mensagens, webhooks, agendamentos ou execução sob demanda iniciam o fluxo.'],['Condição','Uma regra define por onde a execução deve continuar.'],['Ação','Uma capacidade consulta, registra, transforma ou entrega informação.']],source:'https://catalisa.io/workflows/',next:'/agentes/',nextTitle:'A conversa também realiza trabalho.'},agents:{tag:'06 / Agentes IA',title:'Entender.<br>Agir. Encaminhar.',desc:'Contexto e ferramentas aproximam a conversa da operação.',i:3,heading:'A conversa é<br>uma das interfaces.',text:'Agentes combinam instruções, conhecimento e ferramentas. Podem consultar uma agenda, registrar informações e participar de workflows, com limites definidos para cada contexto.',items:[['Papel','Objetivo, contexto e limites definem a atuação.'],['Conhecimento','O acervo da organização orienta as respostas.'],['Ferramentas','Capacidades conectadas permitem agir sobre a operação.']],source:'https://catalisa.io/ai-agents/',next:'/governanca/',nextTitle:'Autonomia pede responsabilidade.'}};
function studyPage(key){const d=STUDIES[key];return chapterNav()+artHero(d.tag,d.title,d.desc,moduleArt(d.i,'study-sculpture'),key+'-art')+fSection(`<div class="reading-pair"><h2>${d.heading}</h2><p>${d.text}</p></div>`)+fSection(`<div class="study-process">${d.items.map(([n,t],i)=>quietDetails(`<small>0${i+1}</small> ${n}`,`<p>${t}</p>`)).join('')}</div>`)+(key==='studio'?fSection(`<div class="intent-study">${eyebrow('Exemplo ilustrativo de intenção')}<blockquote>“Organize o atendimento.<br>Encontre um horário<br>na agenda real.”</blockquote>${flow(['Mensagem','Contexto','Agenda','Registro'])}${link('/composicoes/','Explore esta combinação')}</div>`):key==='workflows'?fSection(`<div class="workflow-exhibit">${eyebrow('Fluxo ilustrativo')}${fWorkflow(2)}<p class="small-note">Representação conceitual. Não executa chamadas reais.</p></div>`):fSection(`<div class="reading-pair"><h2>Uma pessoa<br>continua responsável.</h2><div><p>No Med, o profissional libera o registro. No Recrutamento, o parecer exige aprovação. No Jurídico, a análise permanece com o advogado.</p>${link('/ecossistema/','Veja os produtos')}</div></div>`))+fSection(quietDetails('Referência e contexto',source(d.source)))+nextChapter(d.next,d.nextTitle,'Continue explorando a plataforma.')}
studio=()=>studyPage('studio');workflows=()=>studyPage('workflows');agents=()=>studyPage('agents');
const originalGovernance=governance,originalDevelopers=developers;
governance=()=>chapterNav()+originalGovernance()+nextChapter('/desenvolvedores/','A responsabilidade está no contrato.','Encontre a referência técnica de cada capacidade.');
developers=()=>chapterNav()+originalDevelopers()+nextChapter('/capacidades/','Encontre a peça certa.','Explore contratos, limites e estágios no catálogo.');
const priorProduct=productPage,priorPlatform=platformPage,priorBlock=blockPage;
productPage=function(p){return `<nav class="product-subnav container" aria-label="Produtos"><a href="/ecossistema/">← Ecossistema</a>${PRODUCTS.map(x=>`<a href="/ecossistema/${x.slug}/" ${x.slug===p.slug?'aria-current="page"':''}>${x.name}</a>`).join('')}</nav>`+priorProduct(p)+nextChapter('/ecossistema/'+PRODUCTS[(PRODUCTS.indexOf(p)+1)%PRODUCTS.length].slug+'/','Outra expressão da mesma base.','Continue pelo ecossistema.')};
blockPage=function(b){return priorBlock(b)+nextChapter('/capacidades/','Volte à visão do conjunto.','Explore outras capacidades e seus contratos.')};
const priorBind=bindFaithful;
bindFaithful=function(){priorBind();$$('.explore-menu').forEach(el=>{document.addEventListener('keydown',e=>{if(e.key==='Escape')el.open=false});document.addEventListener('click',e=>{if(!el.contains(e.target))el.open=false})});if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches&&'IntersectionObserver' in window){const ob=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');ob.unobserve(e.target)}}),{threshold:.08});$$('.art-hero-piece,.architecture-exhibit,.principle-trio').forEach(el=>{el.classList.add('reveal-art');ob.observe(el)})}};
/* Deeper content stays available without competing with the main narrative. */
const fullGallery=gallery;
gallery=function(product=''){if(!product)return fullGallery();const shots=window.SCREENSHOTS.filter(s=>s.product===product);return `<div class="screen-gallery">${shots.slice(0,2).map(screenCard).join('')}</div>${quietDetails('Explore as demais interfaces',`<div class="screen-gallery">${shots.slice(2).map(screenCard).join('')}</div>`)}`};
governance=function(){return chapterNav()+artHero('07 / Governança','Confiança se<br>constrói no detalhe.','Identidade, versões e evidências dão forma à responsabilidade.',moduleArt(0,'study-sculpture'),'agents-art')+fSection(`<div class="reading-pair"><h2>Quem pode.<br>O que aconteceu.<br>Qual versão.</h2><p>Permissões delimitam a ação. Registros preservam o contexto. Versões tornam uma decisão rastreável. Cada capacidade declara seus contratos e seus limites.</p></div>`)+fSection(`<div class="layer-explorer"><div><h2>Responsabilidade<br>em cada camada.</h2></div><div>${[['Identidade','O IAM associa usuário, organização e permissões ao acesso.','iam'],['Rastreabilidade','Decision Engine registra a versão da política utilizada na execução.','decision-engine'],['Evidência','Biometrics associa verificações e evidência assinada à sessão.','biometrics'],['Maturidade','Produção, Beta e Alpha indicam estágios diferentes. Consulte os limites de cada capacidade.',null]].map(([n,t,s])=>quietDetails(n,`<p>${t}</p>${link(s?'/capacidades/'+s+'/':'/capacidades/','Consultar capacidade e estágio')}`)).join('')}</div></div>`)+fSection(`<div class="reading-pair"><h2>A decisão humana<br>tem seu lugar.</h2><div><p>No Med, o registro preparado pela IA depende da liberação profissional. No Recrutamento, o parecer exige aprovação. No Jurídico, a análise pertence ao advogado.</p>${link('/ecossistema/','Explore as responsabilidades nos produtos')}</div></div>`)+nextChapter('/desenvolvedores/','O contrato torna a base legível.','Encontre as referências técnicas.')};
developers=function(){return chapterNav()+hero('08 / Desenvolvedores','Comece pela<br>responsabilidade.','Encontre a capacidade. Confira o contrato. Construa a integração.','modules')+fSection(`<div class="reading-pair"><h2>APIs, eventos<br>e fronteiras.</h2><div><p>Cada building block documenta seu domínio, as operações que oferece e os dados que recebe. Identidade, permissões, estágio e limites fazem parte da escolha.</p>${actions(link('https://docs.catalisa.app/blocks/','Abrir documentação','button outline'),link('/capacidades/','Explore o catálogo'))}</div></div>`)+fSection(`<div class="contract-study"><div>${eyebrow('Exemplo conceitual / Biometrics')}<h2>Uma sessão.<br>Contratos distintos.</h2></div><div>${[['IAM / API Keys','Identidade e credenciais','iam'],['Biometrics','Captura e decisão da sessão','biometrics'],['File Storage','Mídia e documentos','file-storage'],['Webhooks Engine','Entrega de eventos','webhooks-engine']].map(([n,t,s])=>`<a href="/capacidades/${s}/"><strong>${n}</strong><span>${t}</span><i>↗</i></a>`).join('')}</div></div>`)+fSection(quietDetails('Antes de integrar',`<p>Confira endpoints, permissões, estágio e limites na documentação de cada building block. Os exemplos deste site são representações conceituais; as integrações reais pertencem aos produtos.</p>${source('https://docs.catalisa.app/blocks/')}`))+nextChapter('/capacidades/','Encontre a peça certa.','Explore a biblioteca de capacidades.')};
const hydratedComposition=composition;
composition=function(){const d=compositionData[0];return hydratedComposition().replace('<div id="composition-panel" role="tabpanel"></div>',`<div id="composition-panel" role="tabpanel"><div class="composition">${art(d.art)}<div>${eyebrow('Composição ilustrativa')}<h3>${d.title}</h3><p>${d.text}</p>${flow(d.nodes)}<div class="tag-list">${d.blocks.map(s=>BLOCKS.find(b=>b.slug===s)).filter(Boolean).map(b=>`<a class="tag" href="${blockLink(b)}">${b.name} ↗</a>`).join('')}</div></div></div></div>`)};
window.bootCatalisa();
